import 'server-only';
import { generateImage } from 'ai';
import { createOpenAI } from '@ai-sdk/openai';
import { createGoogle } from '@ai-sdk/google';
import { getIntegration } from '@/lib/integrations/secrets';
import { providerDown } from '@/lib/ai/model';
import { supabaseAdmin } from '@/lib/supabase/admin';
import type { Member } from '@/lib/integrations/auth';

// Idea covers made on the server: generated by the workspace's image model (OpenAI or Gemini; Claude does not make
// images) from the idea's title, hook and angle, or copied from a picture the web already has (a reference video's
// thumbnail). The file lands in idea-covers under <workspace>/<idea>/ like an uploaded cover. Used by the cover
// route (a member clicking Generate or Use as cover), by new ideas (every idea gets a cover as it lands on the
// Ideas & Research page) and by research runs (each drafted idea).

export const STYLES: Record<string, string> = {
  photo: 'cinematic photograph, shallow depth of field, dramatic natural light, rich color grade',
  bold: 'bold flat graphic design, chunky shapes, saturated two-tone palette, strong contrast, poster-like',
  illustration: 'editorial illustration, textured brush strokes, expressive and warm, limited palette',
  minimal: 'minimal composition, one hero object on a clean gradient backdrop, lots of negative space',
};

const MAX_BYTES = 10 * 1024 * 1024;
const EXT: Record<string, string> = { 'image/png': 'png', 'image/jpeg': 'jpg', 'image/webp': 'webp', 'image/gif': 'gif', 'image/avif': 'avif' };
const blockedHost = (h: string) => /^(localhost|.*\.local|.*\.internal|.*\.localhost)$/i.test(h) || /^\[?[0-9a-f:.]+\]?$/i.test(h);

export class CoverError extends Error { status: number; constructor(message: string, status = 502) { super(message); this.status = status; } }

type IdeaRow = { project_id: string | null; id: string; workspace_id: string; brand_id: string; title: string; hook: string | null; audience: string | null; promise: string | null; cover_path: string | null; cover_mode: string; body: string[] };
type Brand = { name: string; color: string | null; tone: string[] } | null;
type Img = { bytes: Uint8Array; type: string; model: string };

function prompt(i: IdeaRow, brand: Brand, style: string, extra: string) {
  return [
    'A 16:9 YouTube thumbnail background image for a video titled "' + i.title + '".',
    i.hook ? 'The headline that will be placed over it says "' + i.hook + '", so leave a calm area for text.' : 'Leave a calm area for a headline to be placed over it.',
    i.audience ? 'Audience: ' + i.audience + '.' : '',
    i.promise ? 'What the viewer gets: ' + i.promise + '.' : '',
    (i.body || []).slice(0, 2).join(' ').slice(0, 300),
    brand ? 'Brand: ' + brand.name + (brand.color ? ', accent color ' + brand.color : '') + (brand.tone.length ? ', tone ' + brand.tone.slice(0, 3).join(', ') : '') + '.' : '',
    'Style: ' + (STYLES[style] || STYLES.photo) + '.',
    extra ? 'Direction: ' + extra : '',
    'High contrast, eye-catching, instantly readable at a small size. No text, no letters, no numbers, no logos, no watermarks, no borders.',
  ].filter(Boolean).join('\n');
}

// The provider's own words, without the SDK's retry wrapper.
const cleanError = (err: unknown) => String((err as { message?: string })?.message || err || 'The image model failed.').replace(/^Failed after \d+ attempts?\. Last error: /i, '').replace(/^AI_[A-Za-z]+:\s*/, '').slice(0, 300);

// True when the workspace has a provider that can draw. Cheap: one query, no keys.
export async function imageModelConnected(ws: string): Promise<boolean> {
  const { data } = await supabaseAdmin().from('integrations').select('provider').eq('workspace_id', ws).eq('status', 'connected').in('provider', ['openai', 'gemini']).limit(1);
  return !!(data && data.length);
}

// Image models to try, newest first. A key may not have every model (older ones retire, newer ones roll out), so a
// "does not exist" answer moves on to the next one.
const OPENAI_IMAGE = ['gpt-image-2', 'gpt-image-1.5', 'gpt-image-1'];
const GEMINI_IMAGE = ['gemini-3.1-flash-image-preview', 'gemini-2.5-flash-image'];
const noSuchModel = (err: unknown) => {
  const e = err as { statusCode?: number; status?: number; message?: string } | null;
  return !!e && (Number(e.statusCode || e.status) === 404 || /does not exist|not found|not supported|unsupported model|invalid model|no longer available|deprecated/i.test(String(e.message || '')));
};

// OpenAI first, then Gemini: the next model or provider is tried when one is missing for this key, out of credits,
// rejects its key or is down (the same rule as text models). Bad prompts and safety refusals are not retried.
async function imageFromModel(ws: string, text: string): Promise<Img> {
  const [openai, gemini] = await Promise.all([getIntegration(ws, 'openai').catch(() => null), getIntegration(ws, 'gemini').catch(() => null)]);
  if (!openai && !gemini) throw new CoverError('Connect OpenAI or Gemini in Integrations to generate covers. Claude does not make images.', 409);
  const tries: { label: string; run: () => Promise<Img> }[] = [];
  if (openai) for (const id of OPENAI_IMAGE) tries.push({ label: 'OpenAI ' + id, run: async () => {
    const r = await generateImage({ model: createOpenAI({ apiKey: openai.secret.apiKey }).image(id), prompt: text, size: '1536x1024', providerOptions: { openai: { quality: 'medium' } } });
    return { bytes: r.image.uint8Array, type: r.image.mediaType || 'image/png', model: 'OpenAI ' + id };
  } });
  if (gemini) for (const id of GEMINI_IMAGE) tries.push({ label: 'Gemini ' + id, run: async () => {
    const r = await generateImage({ model: createGoogle({ apiKey: gemini.secret.apiKey }).image(id), prompt: text, aspectRatio: '16:9' });
    return { bytes: r.image.uint8Array, type: r.image.mediaType || 'image/png', model: 'Gemini ' + id };
  } });
  const failed: string[] = [];
  for (const t of tries) {
    try { return await t.run(); } catch (err) {
      failed.push(t.label + ': ' + cleanError(err));
      if (!providerDown(err) && !noSuchModel(err)) break;
    }
  }
  throw new CoverError(failed.join('  ·  '), 502);
}

async function imageFromUrl(raw: string): Promise<Img> {
  let u: URL;
  try { u = new URL(raw); } catch { throw new CoverError('That is not a valid image link.', 400); }
  if ((u.protocol !== 'http:' && u.protocol !== 'https:') || blockedHost(u.hostname)) throw new CoverError('That image link cannot be used.', 400);
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), 15000);
  try {
    const res = await fetch(u.href, { headers: { 'user-agent': 'Mozilla/5.0 (compatible; FTGU-Studio/1.0)', accept: 'image/*' }, redirect: 'follow', signal: ctrl.signal });
    const type = (res.headers.get('content-type') || '').split(';')[0].trim().toLowerCase();
    if (!res.ok) throw new CoverError('The image could not be downloaded (' + res.status + ').');
    if (!EXT[type]) throw new CoverError('That link is not a JPG, PNG, WebP, GIF or AVIF image.', 415);
    const buf = new Uint8Array(await res.arrayBuffer());
    if (buf.length > MAX_BYTES) throw new CoverError('That image is over 10 MB.', 413);
    if (!buf.length) throw new CoverError('The image came back empty.');
    return { bytes: buf, type, model: '' };
  } finally { clearTimeout(t); }
}

export type CoverRequest = { ideaId: string; ws: string; mode: 'generate' | 'url'; style?: string; prompt?: string; url?: string;
  // Only set a cover when the idea has none yet (new ideas and research drafts).
  onlyIfMissing?: boolean;
  // The member whose session saves the idea row (RLS decides). Without one, the secret-key client saves it.
  member?: Member | null; actorId?: string; actorLabel?: string };
export type CoverResult = { path: string; url: string; coverMode: string; model: string; skipped?: boolean };

export async function makeIdeaCover(q: CoverRequest): Promise<CoverResult> {
  const admin = supabaseAdmin();
  const reader = q.member ? q.member.supabase : admin;
  const { data: idea } = await reader.from('ideas').select('id, project_id, workspace_id, brand_id, title, hook, audience, promise, cover_path, cover_mode, body').eq('id', q.ideaId).eq('workspace_id', q.ws).maybeSingle();
  if (!idea) throw new CoverError('That idea is not available.', 404);
  const i = idea as IdeaRow;
  if (q.onlyIfMissing && i.cover_path) return { path: i.cover_path, url: '', coverMode: i.cover_mode, model: '', skipped: true };

  let img: Img;
  if (q.mode === 'url') img = await imageFromUrl(String(q.url || ''));
  else {
    const { data: brand } = await reader.from('brand_kits').select('name, color, tone').eq('id', i.brand_id).maybeSingle();
    img = await imageFromModel(q.ws, prompt(i, brand as Brand, String(q.style || 'photo'), String(q.prompt || '').slice(0, 400)));
  }

  const path = q.ws + '/' + i.id + '/cover-' + (q.mode === 'url' ? 'ref' : 'ai') + '-' + Date.now() + '.' + (EXT[img.type] || 'png');
  const up = await admin.storage.from('idea-covers').upload(path, img.bytes, { upsert: false, contentType: img.type });
  if (up.error) throw new CoverError('The cover could not be stored: ' + up.error.message);

  const coverMode = i.cover_mode === 'hook' ? 'both' : i.cover_mode;
  let upd = reader.from('ideas').update({ cover_path: path, cover_mode: coverMode, cover_focal_x: 50, cover_focal_y: 50 }).eq('id', i.id);
  if (q.onlyIfMissing) upd = upd.is('cover_path', null);
  const saved = await upd.select('id');
  if (saved.error || !saved.data || !saved.data.length) {
    await admin.storage.from('idea-covers').remove([path]);
    if (q.onlyIfMissing && !saved.error) return { path: '', url: '', coverMode: i.cover_mode, model: img.model, skipped: true };
    throw new CoverError(saved.error ? saved.error.message : 'You cannot change this idea.', 403);
  }
  if (i.cover_path && i.cover_path !== path && !i.project_id) await admin.storage.from('idea-covers').remove([i.cover_path]).catch(() => {});

  const action = q.mode === 'url' ? 'set the cover from a reference' : 'generated a cover with ' + img.model;
  if (q.member) {
    const logged = await q.member.supabase.rpc('log_activity', { p_category: 'idea', p_action: action, p_target_label: i.title, p_project: null, p_idea: i.id, p_event: null, p_quote: null, p_external: false });
    if (logged.error) console.warn('log_activity', logged.error.message);
  } else if (q.actorId) {
    await admin.from('activity_log').insert({ workspace_id: q.ws, actor_id: q.actorId, actor_label: q.actorLabel || '', category: 'idea', action, target_type: 'idea', target_id: i.id, target_label: i.title, idea_id: i.id, source: 'api' });
  }
  const signed = await admin.storage.from('idea-covers').createSignedUrl(path, 3600);
  return { path, url: signed.data?.signedUrl || '', coverMode, model: img.model };
}

// Covers for several new ideas at once (research drafts), a few at a time and inside a time budget. Failures are
// logged and skipped: the ideas are already saved and a member can generate later.
export async function coverNewIdeas(ids: string[], ws: string, m: Member, budgetMs: number) {
  if (!ids.length || !(await imageModelConnected(ws))) return;
  const label = (m.ctx.profile && (String(m.ctx.profile.full_name || '').split(' ')[0] || m.ctx.profile.email)) || '';
  const started = Date.now();
  const queue = ids.slice();
  const worker = async () => {
    for (let id = queue.shift(); id; id = queue.shift()) {
      if (Date.now() - started > budgetMs) return;
      try { await makeIdeaCover({ ideaId: id, ws, mode: 'generate', onlyIfMissing: true, actorId: m.ctx.user_id, actorLabel: label }); }
      catch (err) { console.warn('idea cover', id, cleanError(err)); if (err instanceof CoverError && err.status === 409) return; }
    }
  };
  await Promise.all([worker(), worker(), worker()]);
}
